     1→/**
     2→ * FK Approved Contracts - Operations view for downloading approved contracts
     3→ */
     4→import React, { useState, useEffect, useCallback } from 'react';
     5→import {
     6→  Box,
     7→  Typography,
     8→  Table,
     9→  TableBody,
    10→  TableCell,
    11→  TableContainer,
    12→  TableHead,
    13→  TableRow,
    14→  Paper,
    15→  Button,
    16→  Chip,
    17→  IconButton,
    18→  Tooltip,
    19→  Alert,
    20→  CircularProgress,
    21→  TableSortLabel,
    22→  Collapse,
    23→  TextField,
    24→  Stack,
    25→  FormControl,
    26→  FormLabel,
    27→  FormGroup,
    28→  FormControlLabel,
    29→  Checkbox,
    30→  Badge,
    31→} from '@mui/material';
    32→import {
    33→  PictureAsPdf as PdfIcon,
    34→  Info as InfoIcon,
    35→  CheckCircle as CheckCircleIcon,
    36→  FilterList as FilterListIcon,
    37→  Clear as ClearIcon,
    38→  FileDownload as FileDownloadIcon,
    39→} from '@mui/icons-material';
    40→import { operationsService } from '../../services/operationsService';
    41→import type { ContractGeneration, OperationsSortOrder, OperationsFilterParams } from '../../types/legal';
    42→import { exportContractsToPDF } from '../../utils/pdfExport';
    43→
    44→// Mapping of frontend sort field names to backend database fields
    45→const SORT_FIELD_MAP: Record<string, string> = {
    46→  'contract_id': 'contract_id',
    47→  'contract_type': 'contract_type',
    48→  'nombre_importador': 'data_snapshot->nombre_importador',
    49→  'client_nit': 'client_nit',
    50→  'cupo_plataforma': 'data_snapshot->cupo_plataforma',
    51→  'reviewed_at': 'reviewed_at',
    52→};
    53→
    54→const FKApprovedContracts: React.FC = () => {
    55→  const [contracts, setContracts] = useState<ContractGeneration[]>([]);
    56→  const [loading, setLoading] = useState(true);
    57→  const [error, setError] = useState<string | null>(null);
    58→  const [downloadingId, setDownloadingId] = useState<string | null>(null);
    59→  const [sortBy, setSortBy] = useState<string>('reviewed_at');
    60→  const [sortOrder, setSortOrder] = useState<OperationsSortOrder>('desc');
    61→  const [exportingPDF, setExportingPDF] = useState(false);
    62→
    63→  // Filter state
    64→  const [showFilters, setShowFilters] = useState(false);
    65→  const [filters, setFilters] = useState<OperationsFilterParams>({});
    66→  const [activeFilterCount, setActiveFilterCount] = useState(0);
    67→
    68→  // Count active filters
    69→  const countActiveFilters = useCallback((filterParams: OperationsFilterParams): number => {
    70→    let count = 0;
    71→    if (filterParams.contract_types && filterParams.contract_types.length > 0) count++;
    72→    if (filterParams.client_name && filterParams.client_name.trim()) count++;
    73→    if (filterParams.client_nit && filterParams.client_nit.trim()) count++;
    74→    if (filterParams.date_from) count++;
    75→    if (filterParams.date_to) count++;
    76→    if (filterParams.cupo_min !== undefined) count++;
    77→    if (filterParams.cupo_max !== undefined) count++;
    78→    return count;
    79→  }, []);
    80→
    81→  const loadApprovedContracts = useCallback(async () => {
    82→    try {
    83→      setLoading(true);
    84→      setError(null);
    85→      // Map frontend field name to backend field name
    86→      const backendSortField = SORT_FIELD_MAP[sortBy] || 'reviewed_at';
    87→      const data = await operationsService.getApprovedContracts(
    88→        filters,
    89→        backendSortField,
    90→        sortOrder
    91→      );
    92→      setContracts(data);
    93→    } catch (err) {
    94→      console.error('Error loading approved contracts:', err);
    95→      setError('Error al cargar los contratos aprobados');
    96→    } finally {
    97→      setLoading(false);
    98→    }
    99→  }, [filters, sortBy, sortOrder]);
   100→
   101→  useEffect(() => {
   102→    loadApprovedContracts();
   103→  }, [loadApprovedContracts]);
   104→
   105→  // Update active filter count when filters change
   106→  useEffect(() => {
   107→    setActiveFilterCount(countActiveFilters(filters));
   108→  }, [filters, countActiveFilters]);
   109→
   110→  const handleSortRequest = (column: string) => {
   111→    // If clicking the current sort column, toggle the order
   112→    if (sortBy === column) {
   113→      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
   114→    } else {
   115→      // If clicking a new column, set it as the sort column with descending order
   116→      setSortBy(column);
   117→      setSortOrder('desc');
   118→    }
   119→  };
   120→
   121→  // Filter handlers
   122→  const handleContractTypeChange = (type: string, checked: boolean) => {
   123→    setFilters((prev) => {
   124→      const currentTypes = prev.contract_types || [];
   125→      const newTypes = checked
   126→        ? [...currentTypes, type]
   127→        : currentTypes.filter((t) => t !== type);
   128→      return { ...prev, contract_types: newTypes.length > 0 ? newTypes : undefined };
   129→    });
   130→  };
   131→
   132→  const handleClearFilters = () => {
   133→    setFilters({});
   134→    setShowFilters(false);
   135→  };
   136→
   137→  const handleDownloadPDF = async (contract: ContractGeneration) => {
   138→    if (!contract.approved_document_url) {
   139→      alert('No hay PDF disponible para este contrato');
   140→      return;
   141→    }
   142→
   143→    try {
   144→      setDownloadingId(contract.id);
   145→
   146→      // Download via backend API endpoint
   147→      const blob = await operationsService.downloadApprovedContractPdf(contract.id);
   148→      const url = window.URL.createObjectURL(blob);
   149→      const link = document.createElement('a');
   150→      link.href = url;
   151→      link.download = `contrato_${contract.contract_id}_aprobado.pdf`;
   152→      document.body.appendChild(link);
   153→      link.click();
   154→      document.body.removeChild(link);
   155→      window.URL.revokeObjectURL(url);
   156→    } catch (err) {
   157→      console.error('Error downloading PDF:', err);
   158→      alert('Error al descargar el PDF');
   159→    } finally {
   160→      setDownloadingId(null);
   161→    }
   162→  };
   163→
   164→  const handleExportPDF = async () => {
   165→    try {
   166→      setExportingPDF(true);
   167→      exportContractsToPDF(contracts);
   168→    } catch (err) {
   169→      console.error('Error exporting PDF:', err);
   170→      alert('Error al exportar PDF');
   171→    } finally {
   172→      setExportingPDF(false);
   173→    }
   174→  };
   175→
   176→  const formatDate = (dateString: string) => {
   177→    return new Date(dateString).toLocaleString('es-CO', {
   178→      year: 'numeric',
   179→      month: 'long',
   180→      day: 'numeric',
   181→      hour: '2-digit',
   182→      minute: '2-digit',
   183→    });
   184→  };
   185→
   186→  const formatCurrency = (amount: number) => {
   187→    return new Intl.NumberFormat('es-CO', {
   188→      style: 'currency',
   189→      currency: 'COP',
   190→      minimumFractionDigits: 0,
   191→    }).format(amount);
   192→  };
   193→
   194→  const getContractTypeBadge = (contractType: string) => {
   195→    if (contractType === 'otrosi') {
   196→      return {
   197→        label: 'Otrosí No. 1',
   198→        color: 'warning' as const,
   199→      };
   200→    }
   201→    if (contractType === 'inventario_bodega') {
   202→      return {
   203→        label: 'Inventario Bodega 3ro',
   204→        color: 'success' as const,
   205→      };
   206→    }
   207→    return {
   208→      label: 'Activos',
   209→      color: 'info' as const,
   210→    };
   211→  };
   212→
   213→  if (loading) {
   214→    return (
   215→      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 300 }}>
   216→        <CircularProgress />
   217→      </Box>
   218→    );
   219→  }
   220→
   221→  if (error) {
   222→    return <Alert severity="error">{error}</Alert>;
   223→  }
   224→
   225→  if (contracts.length === 0 && activeFilterCount === 0) {
   226→    return (
   227→      <Alert severity="info" icon={<InfoIcon />}>
   228→        No hay contratos aprobados disponibles para descarga.
   229→      </Alert>
   230→    );
   231→  }
   232→
   233→  return (
   234→    <Box>
   235→      <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
   236→        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
   237→          <Typography variant="h6" sx={{ fontWeight: 600 }}>
   238→            Contratos Aprobados ({contracts.length})
   239→          </Typography>
   240→          {activeFilterCount > 0 && (
   241→            <Chip
   242→              label={`${activeFilterCount} filtro${activeFilterCount > 1 ? 's' : ''} activo${activeFilterCount > 1 ? 's' : ''}`}
   243→              size="small"
   244→              color="primary"
   245→              onDelete={handleClearFilters}
   246→            />
   247→          )}
   248→        </Box>
   249→        <Box sx={{ display: 'flex', gap: 1 }}>
   250→          <Badge badgeContent={activeFilterCount} color="primary">
   251→            <Button
   252→              variant={showFilters ? 'contained' : 'outlined'}
   253→              size="small"
   254→              onClick={() => setShowFilters(!showFilters)}
   255→              startIcon={<FilterListIcon />}
   256→              sx={{ textTransform: 'none' }}
   257→            >
   258→              Filtros
   259→            </Button>
   260→          </Badge>
   261→          <Button
   262→            variant="outlined"
   263→            size="small"
   264→            onClick={loadApprovedContracts}
   265→            sx={{ textTransform: 'none' }}
   266→          >
   267→            Actualizar
   268→          </Button>
   269→          <Button
   270→            variant="contained"
   271→            size="small"
   272→            onClick={handleExportPDF}
   273→            disabled={contracts.length === 0 || exportingPDF}
   274→            startIcon={exportingPDF ? <CircularProgress size={16} /> : <FileDownloadIcon />}
   275→            sx={{ textTransform: 'none' }}
   276→          >
   277→            {exportingPDF ? 'Exportando...' : 'Exportar PDF'}
   278→          </Button>
   279→        </Box>
   280→      </Box>
   281→
   282→      {/* Filter Panel */}
   283→      <Collapse in={showFilters}>
   284→        <Paper sx={{ p: 3, mb: 3, bgcolor: 'grey.50', border: 1, borderColor: 'divider' }}>
   285→          <Stack spacing={3}>
   286→            {/* Contract Type Filter */}
   287→            <FormControl component="fieldset">
   288→              <FormLabel component="legend" sx={{ fontWeight: 600, mb: 1 }}>
   289→                Tipo de Contrato
   290→              </FormLabel>
   291→              <FormGroup row>
   292→                <FormControlLabel
   293→                  control={
   294→                    <Checkbox
   295→                      checked={filters.contract_types?.includes('activos') || false}
   296→                      onChange={(e) => handleContractTypeChange('activos', e.target.checked)}
   297→                    />
   298→                  }
   299→                  label={<Chip label="Activos" color="info" size="small" />}
   300→                />
   301→                <FormControlLabel
   302→                  control={
   303→                    <Checkbox
   304→                      checked={filters.contract_types?.includes('otrosi') || false}
   305→                      onChange={(e) => handleContractTypeChange('otrosi', e.target.checked)}
   306→                    />
   307→                  }
   308→                  label={<Chip label="Otrosí No. 1" color="warning" size="small" />}
   309→                />
   310→                <FormControlLabel
   311→                  control={
   312→                    <Checkbox
   313→                      checked={filters.contract_types?.includes('inventario_bodega') || false}
   314→                      onChange={(e) => handleContractTypeChange('inventario_bodega', e.target.checked)}
   315→                    />
   316→                  }
   317→                  label={<Chip label="Inventario Bodega 3ro" color="success" size="small" />}
   318→                />
   319→              </FormGroup>
   320→            </FormControl>
   321→
   322→            {/* Text Filters Row */}
   323→            <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
   324→              <TextField
   325→                label="Nombre del Cliente"
   326→                placeholder="Buscar por nombre..."
   327→                value={filters.client_name || ''}
   328→                onChange={(e) => setFilters({ ...filters, client_name: e.target.value || undefined })}
   329→                size="small"
   330→                sx={{ flex: '1 1 300px' }}
   331→              />
   332→              <TextField
   333→                label="NIT"
   334→                placeholder="Buscar por NIT..."
   335→                value={filters.client_nit || ''}
   336→                onChange={(e) => setFilters({ ...filters, client_nit: e.target.value || undefined })}
   337→                size="small"
   338→                sx={{ flex: '1 1 200px' }}
   339→              />
   340→            </Box>
   341→
   342→            {/* Date and Cupo Filters Row */}
   343→            <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
   344→              <TextField
   345→                label="Fecha Desde"
   346→                type="date"
   347→                value={filters.date_from || ''}
   348→                onChange={(e) => setFilters({ ...filters, date_from: e.target.value || undefined })}
   349→                InputLabelProps={{ shrink: true }}
   350→                size="small"
   351→                sx={{ flex: '1 1 200px' }}
   352→              />
   353→              <TextField
   354→                label="Fecha Hasta"
   355→                type="date"
   356→                value={filters.date_to || ''}
   357→                onChange={(e) => setFilters({ ...filters, date_to: e.target.value || undefined })}
   358→                InputLabelProps={{ shrink: true }}
   359→                size="small"
   360→                sx={{ flex: '1 1 200px' }}
   361→              />
   362→              <TextField
   363→                label="Cupo Mínimo"
   364→                type="number"
   365→                placeholder="0"
   366→                value={filters.cupo_min !== undefined ? filters.cupo_min : ''}
   367→                onChange={(e) => {
   368→                  const val = e.target.value ? parseFloat(e.target.value) : undefined;
   369→                  setFilters({ ...filters, cupo_min: val });
   370→                }}
   371→                size="small"
   372→                sx={{ flex: '1 1 150px' }}
   373→              />
   374→              <TextField
   375→                label="Cupo Máximo"
   376→                type="number"
   377→                placeholder="999999999"
   378→                value={filters.cupo_max !== undefined ? filters.cupo_max : ''}
   379→                onChange={(e) => {
   380→                  const val = e.target.value ? parseFloat(e.target.value) : undefined;
   381→                  setFilters({ ...filters, cupo_max: val });
   382→                }}
   383→                size="small"
   384→                sx={{ flex: '1 1 150px' }}
   385→              />
   386→            </Box>
   387→
   388→            {/* Action Buttons */}
   389→            <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
   390→              <Button
   391→                variant="outlined"
   392→                size="small"
   393→                onClick={handleClearFilters}
   394→                startIcon={<ClearIcon />}
   395→                sx={{ textTransform: 'none' }}
   396→              >
   397→                Limpiar Filtros
   398→              </Button>
   399→            </Box>
   400→          </Stack>
   401→        </Paper>
   402→      </Collapse>
   403→
   404→      {/* Empty state with filters active */}
   405→      {contracts.length === 0 && activeFilterCount > 0 && (
   406→        <Alert severity="info" icon={<InfoIcon />} sx={{ mb: 3 }}>
