   438→              </TableCell>
   439→              <TableCell sx={{ fontWeight: 600 }}>
   440→                <TableSortLabel
   441→                  active={sortBy === 'contract_type'}
   442→                  direction={sortBy === 'contract_type' ? sortOrder : 'desc'}
   443→                  onClick={() => handleSortRequest('contract_type')}
   444→                >
   445→                  Tipo
   446→                </TableSortLabel>
   447→              </TableCell>
   448→              <TableCell sx={{ fontWeight: 600 }}>
   449→                <TableSortLabel
   450→                  active={sortBy === 'nombre_importador'}
   451→                  direction={sortBy === 'nombre_importador' ? sortOrder : 'desc'}
   452→                  onClick={() => handleSortRequest('nombre_importador')}
   453→                >
   454→                  Cliente
   455→                </TableSortLabel>
   456→              </TableCell>
   457→              <TableCell sx={{ fontWeight: 600 }}>
   458→                <TableSortLabel
   459→                  active={sortBy === 'client_nit'}
   460→                  direction={sortBy === 'client_nit' ? sortOrder : 'desc'}
   461→                  onClick={() => handleSortRequest('client_nit')}
   462→                >
   463→                  NIT
   464→                </TableSortLabel>
   465→              </TableCell>
   466→              <TableCell sx={{ fontWeight: 600 }}>
   467→                <TableSortLabel
   468→                  active={sortBy === 'cupo_plataforma'}
   469→                  direction={sortBy === 'cupo_plataforma' ? sortOrder : 'desc'}
   470→                  onClick={() => handleSortRequest('cupo_plataforma')}
   471→                >
   472→                  Cupo Aprobado
   473→                </TableSortLabel>
   474→              </TableCell>
   475→              <TableCell sx={{ fontWeight: 600 }}>
   476→                <TableSortLabel
