   530→                </TableCell>
   531→                <TableCell>
   532→                  <Chip
   533→                    icon={<CheckCircleIcon />}
   534→                    label="Aprobado"
   535→                    color="success"
   536→                    size="small"
   537→                    sx={{ fontWeight: 500 }}
   538→                  />
   539→                </TableCell>
   540→                <TableCell align="center">
   541→                  <Tooltip title="Descargar PDF aprobado">
   542→                    <span>
   543→                      <IconButton
   544→                        color="primary"
   545→                        onClick={() => handleDownloadPDF(contract)}
   546→                        disabled={!contract.approved_document_url || downloadingId === contract.id}
   547→                        size="small"
   548→                      >
   549→                        {downloadingId === contract.id ? (
   550→                          <CircularProgress size={20} />
