   554→                      </IconButton>
   555→                    </span>
   556→                  </Tooltip>
   557→                  {!contract.approved_document_url && (
   558→                    <Tooltip title="PDF no disponible">
   559→                      <InfoIcon color="disabled" fontSize="small" sx={{ ml: 1 }} />
   560→                    </Tooltip>
   561→                  )}
   562→                </TableCell>
   563→              </TableRow>
   564→            ))}
   565→          </TableBody>
   566→        </Table>
   567→      </TableContainer>
   568→
   569→      <Box sx={{ mt: 2 }}>
   570→        <Alert severity="info" icon={<InfoIcon />}>
   571→          <Typography variant="body2">
   572→            <strong>Instrucciones:</strong> Haga clic en el ícono <PdfIcon fontSize="small" sx={{ verticalAlign: 'middle' }} /> para descargar el PDF aprobado del contrato. Estos documentos están listos para ser enviados al cliente para su firma.
   573→          </Typography>
   574→        </Alert>
   575→      </Box>
   576→    </Box>
   577→  );
   578→};
   579→
   580→export default FKApprovedContracts;
