     1→/**
     2→ * PDF Export Utility - Export approved contracts to PDF
     3→ * Uses jsPDF with jspdf-autotable for professional table formatting
     4→ */
     5→import jsPDF from 'jspdf';
     6→import autoTable from 'jspdf-autotable';
     7→import { format } from 'date-fns';
     8→import { es } from 'date-fns/locale';
     9→import type { ContractGeneration } from '../types/legal';
    10→
    11→// Finkargo brand colors (from theme.ts)
    12→const FINKARGO_COLORS = {
    13→  primaryDark: '#0C147B',
    14→  primaryMain: '#3C47D3',
    15→  coral: '#EB8774',
    16→  success: '#2CA14D',
    17→  grey50: '#F9FAFB',
    18→  grey100: '#F3F4F6',
    19→  grey900: '#111827',
    20→  white: '#FFFFFF',
    21→};
    22→
    23→/**
    24→ * Format contract type to Spanish label
    25→ */
    26→const formatContractTypeLabel = (type: string): string => {
    27→  const typeMap: Record<string, string> = {
    28→    'activos': 'Activos',
    29→    'otrosi': 'Otrosí No. 1',
    30→    'inventario_bodega': 'Inventario Bodega 3ro',
    31→    'pl_co_credito_aval_pj': 'PL CO - Crédito Aval PJ',
    32→    'pl_co_mandato_pj': 'PL CO - Mandato PJ',
    33→    'pl_co_credito_aval_pn': 'PL CO - Crédito Aval PN',
    34→    'pl_co_mandato_pn': 'PL CO - Mandato PN',
    35→    'pl_co_credito_no_aval': 'PL CO - Crédito Sin Aval',
    36→    'pl_co_mandato_no_aval': 'PL CO - Mandato Sin Aval',
    37→    'pl_co_mandato_im': 'PL CO - Mandato IM',
    38→    'pl_co_solicitud_desembolso': 'PL CO - Solicitud Desembolso',
    39→    'pl_co_dian_mandato_im': 'PL CO - DIAN Mandato IM',
    40→  };
    41→  return typeMap[type] || type;
    42→};
    43→
    44→/**
    45→ * Format currency amount to COP format
    46→ */
    47→const formatCurrency = (amount: number): string => {
    48→  return new Intl.NumberFormat('es-CO', {
    49→    style: 'currency',
    50→    currency: 'COP',
    51→    minimumFractionDigits: 0,
    52→  }).format(amount);
    53→};
    54→
    55→/**
    56→ * Format date to DD/MM/YYYY HH:mm format
    57→ */
    58→const formatDate = (dateString: string): string => {
    59→  try {
    60→    return format(new Date(dateString), 'dd/MM/yyyy HH:mm', { locale: es });
    61→  } catch {
    62→    return 'N/A';
    63→  }
    64→};
    65→
    66→/**
    67→ * Export standard contracts (Activos, Otrosí, Inventario) to PDF
    68→ */
    69→export const exportContractsToPDF = (contracts: ContractGeneration[]): void => {
    70→  try {
    71→    // Create PDF document (A4, portrait)
    72→    const doc = new jsPDF({
    73→      orientation: 'portrait',
    74→      unit: 'mm',
    75→      format: 'a4',
    76→    });
    77→
    78→    // Set document properties
    79→    doc.setProperties({
    80→      title: 'Contratos Aprobados - Finkargo',
    81→      subject: 'Lista de contratos aprobados',
    82→      author: 'Finkargo Automation Hub',
    83→      creator: 'Finkargo Automation Hub',
    84→    });
    85→
    86→    // Add title
    87→    doc.setFontSize(18);
    88→    doc.setTextColor(FINKARGO_COLORS.primaryDark);
    89→    doc.setFont('helvetica', 'bold');
    90→    doc.text('Contratos Aprobados - Finkargo', 14, 20);
    91→
    92→    // Add export metadata
    93→    doc.setFontSize(10);
    94→    doc.setTextColor(FINKARGO_COLORS.grey900);
    95→    doc.setFont('helvetica', 'normal');
    96→    const exportDate = format(new Date(), "dd 'de' MMMM 'de' yyyy, HH:mm", { locale: es });
    97→    doc.text(`Fecha de exportación: ${exportDate}`, 14, 28);
    98→    doc.text(`Total de contratos: ${contracts.length}`, 14, 33);
    99→
   100→    // Prepare table data
   101→    const tableData = contracts.map((contract) => [
   102→      contract.contract_id,
   103→      formatContractTypeLabel(contract.contract_type || 'activos'),
   104→      contract.data_snapshot?.nombre_importador || 'N/A',
   105→      contract.client_nit,
   106→      formatCurrency(contract.data_snapshot?.cupo_plataforma || 0),
   107→      contract.reviewed_at ? formatDate(contract.reviewed_at) : 'N/A',
   108→      'Aprobado',
   109→    ]);
   110→
   111→    // Generate table with autoTable
   112→    autoTable(doc, {
   113→      head: [['ID Contrato', 'Tipo', 'Cliente', 'NIT', 'Cupo Aprobado', 'Fecha Aprobación', 'Estado']],
   114→      body: tableData,
   115→      startY: 40,
   116→      theme: 'grid',
   117→      styles: {
   118→        fontSize: 9,
   119→        cellPadding: 3,
   120→        overflow: 'linebreak',
   121→        halign: 'left',
   122→        valign: 'middle',
   123→      },
   124→      headStyles: {
   125→        fillColor: FINKARGO_COLORS.primaryDark,
   126→        textColor: FINKARGO_COLORS.white,
   127→        fontStyle: 'bold',
   128→        fontSize: 9,
   129→        halign: 'center',
   130→      },
   131→      alternateRowStyles: {
   132→        fillColor: FINKARGO_COLORS.grey50,
   133→      },
   134→      columnStyles: {
   135→        0: { cellWidth: 30, fontStyle: 'bold', font: 'courier' }, // ID Contrato (monospace)
   136→        1: { cellWidth: 30 }, // Tipo
   137→        2: { cellWidth: 40 }, // Cliente
   138→        3: { cellWidth: 25 }, // NIT
   139→        4: { cellWidth: 28, halign: 'right', textColor: FINKARGO_COLORS.success }, // Cupo
   140→        5: { cellWidth: 30 }, // Fecha
   141→        6: { cellWidth: 22, halign: 'center', textColor: FINKARGO_COLORS.success }, // Estado
   142→      },
   143→      margin: { left: 14, right: 14 },
   144→      didDrawPage: (data) => {
   145→        // Add page numbers in footer
   146→        const pageCount = doc.getNumberOfPages();
   147→        doc.setFontSize(8);
   148→        doc.setTextColor(FINKARGO_COLORS.grey900);
   149→        doc.setFont('helvetica', 'normal');
   150→        const pageText = `Página ${data.pageNumber} de ${pageCount}`;
   151→        doc.text(pageText, doc.internal.pageSize.width / 2, doc.internal.pageSize.height - 10, {
   152→          align: 'center',
