    // Create workbook
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Contratos Aprobados');

    // Generate filename with current date
    const filename = `contratos_aprobados_${format(new Date(), 'yyyy-MM-dd')}.xlsx`;

    // Save file
    XLSX.writeFile(workbook, filename);
  } catch (error) {
    console.error('Error generating Excel:', error);
    throw new Error('Error al generar el archivo Excel');
  }
};

/**
 * Export Paga Local CO contracts to Excel
 */
export const exportPagaLocalContractsToExcel = (contracts: ContractGeneration[]): void => {
  try {
    // Prepare data for Excel
    const data = contracts.map((contract) => ({
      'ID Contrato': contract.contract_id,
      'Tipo': formatContractTypeLabel(contract.contract_type || 'activos'),
      'Cliente': contract.data_snapshot?.nombre_importador || 'N/A',
      'NIT': contract.client_nit,
      'Cupo Aprobado': contract.data_snapshot?.cupo_plataforma || 0,
      'Fecha Aprobación': contract.reviewed_at ? formatDate(contract.reviewed_at) : 'N/A',
      'Estado': 'Aprobado',
    }));

    // Create worksheet
    const worksheet = XLSX.utils.json_to_sheet(data);

    // Set column widths
    worksheet['!cols'] = [
      { wch: 18 }, // ID Contrato
      { wch: 22 }, // Tipo
      { wch: 35 }, // Cliente
      { wch: 15 }, // NIT
      { wch: 18 }, // Cupo Aprobado
      { wch: 20 }, // Fecha Aprobación
      { wch: 12 }, // Estado
    ];

    // Create workbook
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Paga Local CO');

    // Generate filename with current date
    const filename = `paga_local_co_contratos_aprobados_${format(new Date(), 'yyyy-MM-dd')}.xlsx`;

    // Save file
    XLSX.writeFile(workbook, filename);
  } catch (error) {
    console.error('Error generating Excel:', error);
    throw new Error('Error al generar el archivo Excel');
  }
};

