     1→/**
     2→ * FKPagaLocalCOApprovedContracts - Approved contracts view for Paga Local Colombia
     3→ * Displays all approved Paga Local CO contracts with filtering and download capabilities
     4→ */
     5→import React, { useState, useEffect, useCallback } from 'react';
     6→import {
     7→  Box,
     8→  Typography,
     9→  Table,
    10→  TableBody,
    11→  TableCell,
    12→  TableContainer,
    13→  TableHead,
    14→  TableRow,
    15→  Paper,
    16→  Button,
    17→  Chip,
    18→  IconButton,
    19→  Tooltip,
    20→  Alert,
    21→  CircularProgress,
    22→  TableSortLabel,
    23→  Collapse,
    24→  TextField,
    25→  Stack,
    26→  FormControl,
    27→  FormLabel,
    28→  FormGroup,
    29→  FormControlLabel,
    30→  Checkbox,
    31→  Badge,
    32→} from '@mui/material';
    33→import {
    34→  PictureAsPdf as PdfIcon,
    35→  Info as InfoIcon,
    36→  CheckCircle as CheckCircleIcon,
    37→  FilterList as FilterListIcon,
    38→  Clear as ClearIcon,
    39→  FileDownload as FileDownloadIcon,
    40→} from '@mui/icons-material';
    41→import { operationsService } from '../../services/operationsService';
    42→import type { ContractGeneration, OperationsSortOrder, OperationsFilterParams } from '../../types/legal';
    43→import { exportPagaLocalContractsToPDF } from '../../utils/pdfExport';
    44→
    45→// Paga Local Colombia contract types
    46→const PAGA_LOCAL_CO_TYPES = [
    47→  'pl_co_credito_aval_pj',
    48→  'pl_co_mandato_pj',
    49→  'pl_co_credito_aval_pn',
    50→  'pl_co_mandato_pn',
    51→  'pl_co_credito_no_aval',
    52→  'pl_co_mandato_no_aval',
    53→  'pl_co_mandato_im',
    54→  'pl_co_solicitud_desembolso',
    55→  'pl_co_dian_mandato_im',
    56→];
    57→
    58→// Contract type labels for display
    59→const CONTRACT_TYPE_LABELS: Record<string, { label: string; color: 'primary' | 'secondary' | 'success' | 'warning' | 'info' | 'error' }> = {
    60→  pl_co_credito_aval_pj: { label: 'Crédito Aval PJ', color: 'primary' },
    61→  pl_co_mandato_pj: { label: 'Mandato PJ', color: 'primary' },
    62→  pl_co_credito_aval_pn: { label: 'Crédito Aval PN', color: 'secondary' },
    63→  pl_co_mandato_pn: { label: 'Mandato PN', color: 'secondary' },
    64→  pl_co_credito_no_aval: { label: 'Crédito No Aval', color: 'warning' },
    65→  pl_co_mandato_no_aval: { label: 'Mandato No Aval', color: 'warning' },
    66→  pl_co_mandato_im: { label: 'Mandato (IM)', color: 'info' },
    67→  pl_co_solicitud_desembolso: { label: 'Solicitud Desembolso', color: 'success' },
    68→  pl_co_dian_mandato_im: { label: 'DIAN Mandato (IM)', color: 'error' },
    69→};
    70→
    71→// Mapping of frontend sort field names to backend database fields
    72→const SORT_FIELD_MAP: Record<string, string> = {
    73→  'contract_id': 'contract_id',
    74→  'contract_type': 'contract_type',
    75→  'nombre_importador': 'data_snapshot->nombre_importador',
    76→  'client_nit': 'client_nit',
    77→  'cupo_plataforma': 'data_snapshot->cupo_plataforma',
    78→  'reviewed_at': 'reviewed_at',
    79→};
    80→
    81→const FKPagaLocalCOApprovedContracts: React.FC = () => {
    82→  const [contracts, setContracts] = useState<ContractGeneration[]>([]);
    83→  const [loading, setLoading] = useState(true);
    84→  const [error, setError] = useState<string | null>(null);
    85→  const [downloadingId, setDownloadingId] = useState<string | null>(null);
    86→  const [sortBy, setSortBy] = useState<string>('reviewed_at');
    87→  const [sortOrder, setSortOrder] = useState<OperationsSortOrder>('desc');
    88→  const [exportingPDF, setExportingPDF] = useState(false);
    89→
    90→  // Filter state
    91→  const [showFilters, setShowFilters] = useState(false);
    92→  const [filters, setFilters] = useState<OperationsFilterParams>({});
    93→  const [activeFilterCount, setActiveFilterCount] = useState(0);
    94→
    95→  // Count active filters
    96→  const countActiveFilters = useCallback((filterParams: OperationsFilterParams): number => {
    97→    let count = 0;
    98→    if (filterParams.contract_types && filterParams.contract_types.length > 0) count++;
    99→    if (filterParams.client_name && filterParams.client_name.trim()) count++;
   100→    if (filterParams.client_nit && filterParams.client_nit.trim()) count++;
   101→    if (filterParams.date_from) count++;
   102→    if (filterParams.date_to) count++;
   103→    if (filterParams.cupo_min !== undefined) count++;
   104→    if (filterParams.cupo_max !== undefined) count++;
   105→    return count;
   106→  }, []);
   107→
   108→  const loadApprovedContracts = useCallback(async () => {
   109→    try {
   110→      setLoading(true);
   111→      setError(null);
   112→      // Map frontend field name to backend field name
   113→      const backendSortField = SORT_FIELD_MAP[sortBy] || 'reviewed_at';
   114→
   115→      // Get all approved contracts and filter by Paga Local CO types
   116→      const allContracts = await operationsService.getApprovedContracts(
   117→        {
   118→          ...filters,
   119→          contract_types: filters.contract_types?.length
   120→            ? filters.contract_types.filter((t) => PAGA_LOCAL_CO_TYPES.includes(t))
   121→            : PAGA_LOCAL_CO_TYPES,
   122→        },
   123→        backendSortField,
   124→        sortOrder
   125→      );
   126→
   127→      // Filter to only Paga Local CO contracts
   128→      const pagaLocalContracts = allContracts.filter((c) =>
   129→        PAGA_LOCAL_CO_TYPES.includes(c.contract_type)
   130→      );
   131→
   132→      setContracts(pagaLocalContracts);
   133→    } catch (err) {
   134→      console.error('Error loading approved contracts:', err);
   135→      setError('Error al cargar los contratos aprobados');
   136→    } finally {
   137→      setLoading(false);
   138→    }
   139→  }, [filters, sortBy, sortOrder]);
   140→
   141→  useEffect(() => {
   142→    loadApprovedContracts();
   143→  }, [loadApprovedContracts]);
   144→
   145→  // Update active filter count when filters change
   146→  useEffect(() => {
   147→    setActiveFilterCount(countActiveFilters(filters));
   148→  }, [filters, countActiveFilters]);
   149→
   150→  const handleSortRequest = (column: string) => {
   151→    if (sortBy === column) {
   152→      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
   153→    } else {
   154→      setSortBy(column);
   155→      setSortOrder('desc');
   156→    }
   157→  };
   158→
   159→  // Filter handlers
   160→  const handleContractTypeChange = (type: string, checked: boolean) => {
   161→    setFilters((prev) => {
   162→      const currentTypes = prev.contract_types || [];
   163→      const newTypes = checked
   164→        ? [...currentTypes, type]
   165→        : currentTypes.filter((t) => t !== type);
   166→      return { ...prev, contract_types: newTypes.length > 0 ? newTypes : undefined };
   167→    });
   168→  };
   169→
   170→  const handleClearFilters = () => {
   171→    setFilters({});
   172→    setShowFilters(false);
   173→  };
   174→
   175→  const handleDownloadPDF = async (contract: ContractGeneration) => {
   176→    if (!contract.approved_document_url) {
   177→      alert('No hay PDF disponible para este contrato');
   178→      return;
   179→    }
   180→
   181→    try {
   182→      setDownloadingId(contract.id);
   183→
   184→      const blob = await operationsService.downloadApprovedContractPdf(contract.id);
   185→      const url = window.URL.createObjectURL(blob);
   186→      const link = document.createElement('a');
   187→      link.href = url;
   188→      link.download = `contrato_${contract.contract_id}_aprobado.pdf`;
   189→      document.body.appendChild(link);
   190→      link.click();
   191→      document.body.removeChild(link);
   192→      window.URL.revokeObjectURL(url);
   193→    } catch (err) {
   194→      console.error('Error downloading PDF:', err);
   195→      alert('Error al descargar el PDF');
   196→    } finally {
   197→      setDownloadingId(null);
   198→    }
   199→  };
   200→
   201→  const handleExportPDF = async () => {
   202→    try {
   203→      setExportingPDF(true);
   204→      exportPagaLocalContractsToPDF(contracts);
   205→    } catch (err) {
   206→      console.error('Error exporting PDF:', err);
   207→      alert('Error al exportar PDF');
   208→    } finally {
   209→      setExportingPDF(false);
   210→    }
   211→  };
   212→
   213→  const formatDate = (dateString: string) => {
   214→    return new Date(dateString).toLocaleString('es-CO', {
   215→      year: 'numeric',
   216→      month: 'long',
   217→      day: 'numeric',
   218→      hour: '2-digit',
   219→      minute: '2-digit',
   220→    });
   221→  };
   222→
   223→
   224→  const getContractTypeBadge = (contractType: string) => {
   225→    const config = CONTRACT_TYPE_LABELS[contractType];
   226→    if (config) {
   227→      return config;
   228→    }
   229→    return { label: contractType, color: 'info' as const };
   230→  };
   231→
   232→  if (loading) {
   233→    return (
   234→      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 300 }}>
   235→        <CircularProgress />
   236→      </Box>
   237→    );
   238→  }
   239→
   240→  if (error) {
   241→    return <Alert severity="error">{error}</Alert>;
   242→  }
   243→
   244→  if (contracts.length === 0 && activeFilterCount === 0) {
   245→    return (
   246→      <Alert severity="info" icon={<InfoIcon />}>
   247→        No hay contratos Paga Local Colombia aprobados disponibles para descarga.
   248→      </Alert>
   249→    );
   250→  }
   251→
   252→  return (
   253→    <Box>
   254→      <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
   255→        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
   256→          <Typography variant="h6" sx={{ fontWeight: 600 }}>
   257→            Contratos Paga Local CO Aprobados ({contracts.length})
   258→          </Typography>
   259→          {activeFilterCount > 0 && (
   260→            <Chip
   261→              label={`${activeFilterCount} filtro${activeFilterCount > 1 ? 's' : ''} activo${activeFilterCount > 1 ? 's' : ''}`}
   262→              size="small"
   263→              color="primary"
   264→              onDelete={handleClearFilters}
   265→            />
   266→          )}
   267→        </Box>
   268→        <Box sx={{ display: 'flex', gap: 1 }}>
   269→          <Badge badgeContent={activeFilterCount} color="primary">
   270→            <Button
   271→              variant={showFilters ? 'contained' : 'outlined'}
   272→              size="small"
   273→              onClick={() => setShowFilters(!showFilters)}
   274→              startIcon={<FilterListIcon />}
   275→              sx={{ textTransform: 'none' }}
   276→            >
   277→              Filtros
   278→            </Button>
   279→          </Badge>
   280→          <Button
   281→            variant="outlined"
   282→            size="small"
   283→            onClick={loadApprovedContracts}
   284→            sx={{ textTransform: 'none' }}
   285→          >
   286→            Actualizar
   287→          </Button>
   288→          <Button
