              <TableCell sx={{ fontWeight: 600 }}>
                <TableSortLabel
                  active={sortBy === 'reviewed_at'}
                  direction={sortBy === 'reviewed_at' ? sortOrder : 'desc'}
                  onClick={() => handleSortRequest('reviewed_at')}
                >
                  Fecha Aprobación
                </TableSortLabel>
              </TableCell>
              <TableCell sx={{ fontWeight: 600 }}>Estado</TableCell>
              <TableCell align="center" sx={{ fontWeight: 600 }}>Acciones</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {contracts.map((contract) => (
              <TableRow
                key={contract.id}
                hover
                sx={{ '&:last-child td, &:last-child th': { border: 0 } }}
              >
                <TableCell>
                  <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 500 }}>
                    {contract.contract_id}
                  </Typography>
                </TableCell>
                <TableCell>
                  {(() => {
                    const badge = getContractTypeBadge(contract.contract_type);
                    return (
                      <Chip
                        label={badge.label}
                        color={badge.color}
                        size="small"
                        sx={{ fontWeight: 500 }}
                      />
                    );
                  })()}
                </TableCell>
                <TableCell>
                  <Typography variant="body2" sx={{ fontWeight: 500 }}>
                    {contract.data_snapshot?.nombre_importador || 'N/A'}
                  </Typography>
                </TableCell>
                <TableCell>
                  <Typography variant="body2">{contract.client_nit}</Typography>
                </TableCell>
                <TableCell>
                  <Typography variant="body2" color="text.secondary">
                    {contract.reviewed_at ? formatDate(contract.reviewed_at) : 'N/A'}
                  </Typography>
                </TableCell>
                <TableCell>
                  <Chip
                    icon={<CheckCircleIcon />}
                    label="Aprobado"
                    color="success"
                    size="small"
                    sx={{ fontWeight: 500 }}
                  />
                </TableCell>
                <TableCell align="center">
                  <Tooltip title="Descargar PDF aprobado">
                    <span>
                      <IconButton
                        color="primary"
                        onClick={() => handleDownloadPDF(contract)}
